source = '''def transform(grid):
    g = [row[:] for row in grid]
    n = len(g)
    d = next(k for k in range(1, n + 1) if k * k + k - 1 == n)
    step = d + 1
    starts = [i * step for i in range(d)]

    # Find the full-width or full-height 3-colored band.
    stripe_rows = [r for r in range(n - d + 1)
                   if all(all(g[y][x] == 3 for x in range(n)) for y in range(r, r + d))]
    stripe_cols = [c for c in range(n - d + 1)
                   if all(all(g[y][x] == 3 for y in range(n)) for x in range(c, c + d))]
    horizontal = bool(stripe_rows)
    if horizontal:
        m = stripe_rows[0] // step
        for y in range(starts[m], starts[m] + d):
            for x in range(n):
                if g[y][x] == 3:
                    g[y][x] = 0
    else:
        m = stripe_cols[0] // step
        for y in range(n):
            for x in range(starts[m], starts[m] + d):
                if g[y][x] == 3:
                    g[y][x] = 0

    def tile_nonempty(r, c):
        y0, x0 = starts[r], starts[c]
        return any(grid[y0 + dy][x0 + dx] == 2
                   for dy in range(d) for dx in range(d))

    def get_tile(r, c):
        y0, x0 = starts[r], starts[c]
        return [[grid[y0 + dy][x0 + dx] for dx in range(d)] for dy in range(d)]

    # Existing motifs mark the cell indexed by their position in the tile array.
    for r in range(d):
        for c in range(d):
            if (horizontal and r == m) or ((not horizontal) and c == m):
                continue
            if tile_nonempty(r, c):
                y0, x0 = starts[r], starts[c]
                if grid[y0 + r][x0 + c] == 2:
                    g[y0 + r][x0 + c] = 8

    # The 3-band is a masked motif row/column. Copy the nearest motif from
    # the unmasked side wherever its indexed cell is present.
    for r in range(d):
        for c in range(d):
            if (horizontal and r == m) or ((not horizontal) and c == m):
                source = None
                if horizontal:
                    for sr in range(m + 1, d):
                        if tile_nonempty(sr, c):
                            source = get_tile(sr, c)
                            break
                else:
                    for sc in range(m - 1, -1, -1):
                        if tile_nonempty(r, sc):
                            source = get_tile(r, sc)
                            break
                if source is None or source[r][c] != 2:
                    continue
                y0, x0 = starts[r], starts[c]
                for dy in range(d):
                    for dx in range(d):
                        g[y0 + dy][x0 + dx] = source[dy][dx]
                g[y0 + r][x0 + c] = 8
    return g
'''
